let explodeShader;
let textGraphics;
let textGraphics2;
let vGraphics;
let cGraphics;
let img;


function setup() {
  createCanvas(920, 690, WEBGL);
	explodeShader = createShader(vert, frag);

  textGraphics = createGraphics(width, height);
  textGraphics.background(60);
  textGraphics.fill(255);
  textGraphics.textSize(width / 5);
  textGraphics.textAlign(CENTER, CENTER);
  textGraphics.text("Bye 2024!", width / 2, height / 2);


	textGraphics2 = createGraphics(width, height);
  textGraphics2.background(60);
  textGraphics2.fill(255);
  textGraphics2.textSize(width / 6);
  textGraphics2.textAlign(CENTER, CENTER);
	textGraphics2.text("Happy", width / 2, height / 2 - height/4);
  textGraphics2.text("New Year", width / 2, height / 2);
	textGraphics2.text("2025!", width / 2, height / 2 + height/4);

  vGraphics = createGraphics(width, height);
	cGraphics = createGraphics(width, height);
  vGraphics.loadPixels();
  cGraphics.loadPixels();
  let d = vGraphics.pixelDensity();

  const c = createVector(width*d/2, height*d/2);
  for (let j = 0; j < height * d; j++) {
    for(let i = 0; i < width * d; i++){
      const v = createVector(1,0).rotate(random(TWO_PI));

      const index = (j * width * d + i) * 4;
      vGraphics.pixels[index] = map(v.x, -1,1, 0,255);
      vGraphics.pixels[index + 1] =  map(v.y, -1,1, 0,255);
      vGraphics.pixels[index + 2] = 0;
      vGraphics.pixels[index + 3] = 100;

			cGraphics.pixels[index] = 0; //random(200,255);
      cGraphics.pixels[index + 1] =  random(200,255);
      cGraphics.pixels[index + 2] = random(200,255);
      cGraphics.pixels[index + 3] = 100;
    }
  }
  vGraphics.updatePixels();
	cGraphics.updatePixels();

  shader(explodeShader);
  explodeShader.setUniform("textTexture", textGraphics);
	explodeShader.setUniform("textTexture2", textGraphics2);
  explodeShader.setUniform("vTexture", vGraphics);
	explodeShader.setUniform("cTexture", cGraphics);
	frameRate(50);
}

function draw() {
  background(220);
if (frameCount>160){
  shader(explodeShader);
	const end = 50 * 3 + 3;
	const i = frameCount % (end);
	const explodeSpeed = 1 / 50;
	if( i < end/2 ){
		explodeShader.setUniform("tNum", 0);
  	explodeShader.setUniform("x", Math.pow(explodeSpeed * i, 2));
	}else{
		explodeShader.setUniform("tNum", 1);
		explodeShader.setUniform("x", Math.pow(explodeSpeed * (end - i), 2));
	}

}
	if (frameCount>304) frameCount=80;
  rect(0, 0, width, height);
}

let lapse = 0;    // mouse timer
function mousePressed(){
// prevents mouse press from registering twice
  if (millis() - lapse > 400){
     save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  }
}

// === Tab: shader ===
const frag = `
#ifdef GL_ES
precision mediump float;
#endif

uniform sampler2D textTexture;
uniform sampler2D textTexture2;
uniform sampler2D vTexture;
uniform sampler2D cTexture;
varying vec2 vTexCoord;

uniform float x;
uniform int tNum;

void main() {
 	vec4 cColor = texture2D(vTexture, vTexCoord);
  vec4 vColor = texture2D(vTexture, vTexCoord);
  vec2 move =  (vColor.xy - vec2(0.5, 0.5)) * x;
  vec2 pos = vTexCoord - move;
  pos.x = clamp(pos.x, 0.0, 1.0);
  pos.y = clamp(pos.y, 0.0, 1.0);
  vec4 color = (tNum == 0) ? texture2D(textTexture, pos) : texture2D(textTexture2, pos);
  if( color.x > 0.5 ){
		gl_FragColor = texture2D(cTexture, vTexCoord);
	}else{
  	gl_FragColor = vec4(0.0,0.0,0.0,0.0);
	}
}
`;

const vert = `
#ifdef GL_ES
precision mediump float;
#endif

attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
  positionVec4.y = -positionVec4.y;
  gl_Position = positionVec4;
}
`;

